        assertClose("ray.1.2.1.d.z", 0.991467485492248d, s1.d.z, 1.0e-6);
        assertClose("ray.1.2.1.n.x", 0.20946154752647775d, s1.nrml.x, 1.0e-6);
        assertClose("ray.1.2.1.n.y", -0.16340234702100923d, s1.nrml.y, 1.0e-6);
