        assertClose("ray.1.2.1.dst", 8.22330349407758d, s1.dst, 1.0e-6);
        var s2 = pkg.ray.get(2);
        assertClose("ray.1.2.2.p.x", 16.474482278629665d, s2.p.x, 1.0e-6);
        assertClose("ray.1.2.2.p.y", -11.506685080890334d, s2.p.y, 1.0e-6);
